14	\centering
15	\begin{tabular}{lrrl}
16	\toprule
17	模型 & 参数量 & 样本量 & 成功率 \\
18	\midrule
19	Solution-only & 175M & 1M & 20\% \\
20	Search Former + DU Forer & 15M & 100K & 80\% \\
21	\bottomrule
22	\end{tabular}
23	\caption{Soang 基准的模型对比}
24	\end{table}
